                    "text": cm.group("text").strip(),
                    "to": cm.group("to").strip(),
                }
            )
            continue

        lm = _LINE_RE.match(line)
        if lm:
            speaker = (lm.group("speaker") or "").strip()
            current_items.append(
                {
                    "kind": "line",
                    "speaker": speaker,
                    "text": lm.group("text").strip(),
                    "to": lm.group("to").strip(),
                }
            )
            continue

        raise ValueError(f"Unrecognized line format: {line!r}")

    flush()

    if not order:
        return {"nodes": [], "edges": []}

    nodes_by_id: Dict[str, Dict[str, str]] = {}
    edges: List[Dict[str, str]] = []

