                "text": "",
                "speaker": "",
                "type": "line",
            }
            continue

        is_choice = all(it.get("kind") == "choice" for it in items)
        if is_choice:
            nodes_by_id[section_id] = {
                "id": section_id,
                "text": section_id,
                "speaker": "",
                "type": "choice",
            }
            for it in items:
                to_id = it["to"]
                ensure_node(to_id)
                edges.append({"from": section_id, "to": to_id, "text": it["text"]})
        else:
            line_items = [it for it in items if it.get("kind") == "line"]
            if len(line_items) != len(items):
                raise ValueError(
