    return graph


def _reachable_from_first(graph: Dict[str, Any]) -> Optional[set]:
    nodes = graph.get("nodes", [])
    if not nodes:
        return None
    start = nodes[0]["id"]

    adjacency: Dict[str, List[str]] = {}
    for e in graph.get("edges", []):
        adjacency.setdefault(e["from"], []).append(e["to"])

    seen = set([start])
    q = deque([start])
    while q:
        cur = q.popleft()
        for nxt in adjacency.get(cur, []):
            if nxt not in seen:
                seen.add(nxt)
                q.append(nxt)
    return seen


def _prune_to_reachable(graph: Dict[str, Any], reachable: set) -> Dict[str, Any]:
    nodes = [n for n in graph.get("nodes", []) if n["id"] in reachable]
