        e
        for e in graph.get("edges", [])
        if e["from"] in reachable and e["to"] in reachable
    ]
    return {"nodes": nodes, "edges": edges}


def _validate_graph(graph: Dict[str, Any]) -> None:
    nodes = graph.get("nodes", [])
    edges = graph.get("edges", [])

    ids = [n.get("id") for n in nodes]
    if len(ids) != len(set(ids)):
        raise ValueError("Duplicate node ids detected")

    id_set = set(ids)
    for e in edges:
        if e.get("from") not in id_set:
            raise ValueError(f"Edge from missing node: {e}")
        if e.get("to") not in id_set:
            raise ValueError(f"Edge to missing node: {e}")

    if nodes:
        reachable = _reachable_from_first(graph) or set()
        unreachable = id_set - reachable
        if unreachable:
            raise ValueError(f"Unreachable nodes exist: {sorted(unreachable)[:10]}")


def graph_to_dot(graph: Dict[str, Any]) -> str:
    def esc(s: str) -> str:
        return (
            s.replace("\\", "\\\\")
            .replace('"', '\\"')
            .replace("\n", "\\n")
            .replace("\r", "")
        )

    lines = ["digraph Dialogue {", "  rankdir=LR;"]

    for n in graph.get("nodes", []):
        node_id = str(n.get("id", ""))
        parts = [node_id, str(n.get("type", ""))]
        if n.get("speaker"):
            parts.append(str(n.get("speaker")))
        label = "\\n".join(parts)
        lines.append(f'  "{esc(node_id)}" [label="{esc(label)}"];')

