    lines = ["digraph Dialogue {", "  rankdir=LR;"]

    for n in graph.get("nodes", []):
        node_id = str(n.get("id", ""))
        parts = [node_id, str(n.get("type", ""))]
        if n.get("speaker"):
            parts.append(str(n.get("speaker")))
        label = "\\n".join(parts)
        lines.append(f'  "{esc(node_id)}" [label="{esc(label)}"];')

    for e in graph.get("edges", []):
        frm = str(e.get("from", ""))
        to = str(e.get("to", ""))
        text = str(e.get("text", ""))
        if text:
            lines.append(
                f'  "{esc(frm)}" -> "{esc(to)}" [label="{esc(text)}"];'
            )
        else:
            lines.append(f'  "{esc(frm)}" -> "{esc(to)}";')

    lines.append("}")
    return "\n".join(lines) + "\n"


def main() -> None:
    script_path = Path("/app/script.txt")
    out_json = Path("/app/dialogue.json")
    out_dot = Path("/app/dialogue.dot")

    text = script_path.read_text(encoding="utf-8")
    graph = parse_script(text)

    out_json.write_text(
        json.dumps(graph, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
    )
    out_dot.write_text(graph_to_dot(graph), encoding="utf-8")


if __name__ == "__main__":
    main()
